use std::{collections::HashMap, fs, io::Write, path::{Path, PathBuf}, sync::Mutex};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tauri::{AppHandle, Emitter, Manager, State};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ModelRecord { pub model_id: String, pub status: String, pub downloaded_bytes: u64, pub total_bytes: u64, pub error: Option<String> }
#[derive(Default)] pub struct ModelStore { pub records: Mutex<HashMap<String, ModelRecord>> }
fn model_dir(app: &AppHandle, model_id: &str) -> Result<PathBuf, String> { let root = app.path().app_data_dir().map_err(|e| e.to_string())?.join("models"); if model_id.is_empty() || model_id.contains('/') || model_id.contains('\\') || model_id.contains("..") { return Err("无效的模型 ID".into()); } fs::create_dir_all(&root).map_err(|e| e.to_string())?; Ok(root.join(model_id)) }
fn catalog(model_id: &str) -> Option<(&'static str, u64)> { match model_id { "u2net" => Some(("https://github.com/xuebinqin/U-2-Net/releases/download/1.0/u2net.pth", 176_000_000)), "u2netp" => Some(("https://github.com/xuebinqin/U-2-Net/releases/download/1.0/u2netp.pth", 5_000_000)), "realesrgan-x4plus" => Some(("https://github.com/xinntao/Real-ESRGAN/releases/download/v0.2.5.0/RealESRGAN_x4plus.pth", 65_000_000)), "realesrgan-anime" => Some(("https://github.com/xinntao/Real-ESRGAN/releases/download/v0.2.5.0/RealESRGAN_x4plus_anime_6B.pth", 18_000_000)), _ => None } }
#[tauri::command] pub fn model_status(app: AppHandle, state: State<'_, ModelStore>) -> Result<HashMap<String, ModelRecord>, String> { let mut records = state.records.lock().map_err(|_| "模型状态锁定失败")?.clone(); for id in ["u2net", "u2netp", "rmbg-2.0", "realesrgan-x4plus", "realesrgan-anime"] { let path = model_dir(&app, id)?.join("model.bin"); let total = catalog(id).map(|item| item.1).unwrap_or(0); records.entry(id.into()).or_insert_with(|| ModelRecord { model_id: id.into(), status: if path.exists() { "installed".into() } else { "uninstalled".into() }, downloaded_bytes: if path.exists() { total } else { 0 }, total_bytes: total, error: None }); } Ok(records) }
#[tauri::command] pub async fn model_download(app: AppHandle, state: State<'_, ModelStore>, model_id: String) -> Result<(), String> { let (url, total) = catalog(&model_id).ok_or_else(|| "该模型暂未配置可下载地址".to_string())?; let dir = model_dir(&app, &model_id)?; fs::create_dir_all(&dir).map_err(|e| e.to_string())?; let temp = dir.join("model.part"); let final_path = dir.join("model.bin"); let start = fs::metadata(&temp).map(|m| m.len()).unwrap_or(0); let client = reqwest::Client::new(); let mut request = client.get(url); if start > 0 { request = request.header(reqwest::header::RANGE, format!("bytes={start}-")); } let mut response = request.send().await.map_err(|e| e.to_string())?; let append = start > 0 && response.status() == reqwest::StatusCode::PARTIAL_CONTENT; let offset = if append { start } else { 0 }; if !append { let _ = fs::remove_file(&temp); response = client.get(url).send().await.map_err(|e| e.to_string())?; } if !response.status().is_success() { return Err(format!("下载失败：{}", response.status())); } let mut file = fs::OpenOptions::new().create(true).write(true).append(append).open(&temp).map_err(|e| e.to_string())?; let mut downloaded = offset; use futures_util::StreamExt; let mut stream = response.bytes_stream(); while let Some(chunk) = stream.next().await { let bytes = chunk.map_err(|e| e.to_string())?; file.write_all(&bytes).map_err(|e| e.to_string())?; downloaded += bytes.len() as u64; let _ = app.emit("model-progress", ModelRecord { model_id: model_id.clone(), status: "downloading".into(), downloaded_bytes: downloaded, total_bytes: total, error: None }); } file.flush().map_err(|e| e.to_string())?; fs::rename(temp, final_path).map_err(|e| e.to_string())?; state.records.lock().map_err(|_| "模型状态锁定失败")?.insert(model_id.clone(), ModelRecord { model_id, status: "installed".into(), downloaded_bytes: total, total_bytes: total, error: None }); Ok(()) }
#[tauri::command] pub fn model_pause(_model_id: String) -> Result<(), String> { Ok(()) }
#[tauri::command] pub fn model_cancel(app: AppHandle, model_id: String) -> Result<(), String> { let path = model_dir(&app, &model_id)?.join("model.part"); let _ = fs::remove_file(path); Ok(()) }
#[tauri::command] pub fn model_delete(app: AppHandle, state: State<'_, ModelStore>, model_id: String) -> Result<(), String> { let dir = model_dir(&app, &model_id)?; if dir.exists() { fs::remove_dir_all(dir).map_err(|e| e.to_string())?; } state.records.lock().map_err(|_| "模型状态锁定失败")?.remove(&model_id); Ok(()) }
fn sha256_file(path: &Path) -> Result<String, String> { let bytes = fs::read(path).map_err(|e| e.to_string())?; let mut hasher = Sha256::new(); hasher.update(bytes); Ok(format!("{:x}", hasher.finalize())) }
#[cfg(test)] mod tests { use super::*; #[test] fn catalog_rejects_unknown() { assert!(catalog("../bad").is_none()); } #[test] fn hashes_file() { let path = std::env::temp_dir().join(format!("draivio-hash-{}", std::process::id())); fs::write(&path, b"abc").unwrap(); assert_eq!(sha256_file(&path).unwrap(), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"); let _ = fs::remove_file(path); } }
